window.__POLYGON_SCRIPT_V2_PARTS__.push("          return;\n        }\n        if (action === 'select-nearest') {\n          selectUnit(state.units[0].id);\n          return;\n        }\n        if (action === 'point-info') {\n          toast('Информация о точке пока не определена');\n          return;\n        }\n        const labels = {\n          'add-point': 'Укажите точку на карте',\n          'add-area': 'Укажите центр области на карте',\n          'add-target': 'Укажите цель на карте',\n          'place-unit': 'Укажите место размещения юнита',\n          'move-selected-unit': 'Укажите новое положение юнита',\n          'rotate-selected-unit': 'Укажите направление юнита',\n          'paint-relief': 'Укажите участок рельефа',\n          'paint-ground': 'Укажите участок покрытия',\n          'paint-roads': 'Укажите участок дороги',\n          'paint-buildings': 'Укажите место здания',\n          'paint-objects': 'Укажите место предмета'\n        };\n        setMapAction(action, labels[action] || 'Укажите место на карте');\n      }\n\n      function togglePanel(side, force) {\n        const isLeft = side === 'left';\n        const panel = isLeft ? els.leftPanel : els.rightPanel;\n        const button = isLeft ? els.collapseLeft : els.collapseRight;\n        const current = isLeft ? state.leftCollapsed : state.rightCollapsed;\n        const next = typeof force === 'boolean' ? force : !current;\n        panel.classList.toggle('is-collapsed', next);\n        if (isLeft) {\n          state.leftCollapsed = next;\n          button.textContent = next ? '›' : '‹';\n          button.setAttribute('aria-label', next ? 'Показать левую панель' : 'Скрыть левую панель');\n        } else {\n          state.rightCollapsed = next;\n          button.textContent = next ? '‹' : '›';\n          button.setAttribute('aria-label', next ? 'Показать правую панель' : 'Скрыть правую панель');\n        }\n      }\n\n      function applyPanelWidths() {\n        document.documentElement.style.setProperty('--left-w', `${state.leftWidth}px`);\n        document.documentElement.style.setProperty('--right-w', `${state.rightWidth}px`);\n      }\n\n      function bindResizer(handle, side) {\n        handle.addEventListener('pointerdown', event => {\n          event.preventDefault();\n          handle.setPointerCapture(event.pointerId);\n          document.body.style.cursor = 'ew-resize';\n          const move = moveEvent => {\n            if (side === 'left') state.leftWidth = Math.max(278, Math.min(560, moveEvent.clientX - 14));\n            else state.rightWidth = Math.max(278, Math.min(560, window.innerWidth - moveEvent.clientX - 14));\n            applyPanelWidths();\n          };\n          const up = upEvent => {\n            handle.releasePointerCapture(upEvent.pointerId);\n            handle.removeEventListener('pointermove', move);\n            handle.removeEventListener('pointerup', up);\n            document.body.style.cursor = '';\n            safeStorageSet(`polygonPrototype.${side}Width`, String(side === 'left' ? state.leftWidth : state.rightWidth));\n          };\n          handle.addEventListener('pointermove', move);\n          handle.addEventListener('pointerup', up);\n        });\n      }\n\n      function openModal(type) {\n        closeDropdowns();\n        state.modalType = type;\n        if (type === 'file') renderFileModal();\n        if (type === 'editors') renderEditorsModal();\n        if (type === 'unit-details') {\n          const unit = ensureUnitDefaults(selectedUnit());\n          if (!unit) return;\n          state.unitModalSnapshot = JSON.stringify(unit);\n          renderUnitDetailsModal();\n        }\n        els.modalBackdrop.classList.add('is-open');\n        setTimeout(() => els.modal.querySelector('button, input, textarea, select')?.focus(), 0);\n      }\n\n      function closeModal(options = {}) {\n        if (state.modalType === 'unit-details' && options.revert && state.unitModalSnapshot) {\n          const restored = JSON.parse(state.unitModalSnapshot);\n          const index = state.units.findIndex(unit => unit.id === restored.id);\n          if (index >= 0) state.units[index] = restored;\n          renderUnits(); renderInspector(); renderWorkspace();\n        }\n        state.modalType = null;\n        state.unitModalSnapshot = null;\n        els.modalBackdrop.classList.remove('is-open');\n        els.modal.innerHTML = '';\n      }\n\n      function profileReadOnlyBlock(title, profileName, rows) {\n        return `\n          <details class=\"profile-readonly\">\n            <summary>${escapeHtml(title)}: ${escapeHtml(profileName)}</summary>\n            <dl class=\"data-list\">${rows.map(([label, value]) => `<div class=\"data-row\"><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl>\n          </details>`;\n      }\n\n      function unitDetailsBody(unit) {\n        if (state.unitDetailsTab === 'basic') {\n          return `\n            <section class=\"compact-section\">\n              <div class=\"compact-section__head\"><span class=\"compact-section__title\">Основное</span></div>\n              <div class=\"compact-section__body\">\n                <div class=\"unit-detail-grid\">\n                  <div class=\"compact-field\"><label>Имя юнита</label><input value=\"${escapeHtml(unit.name)}\" data-unit-detail-field=\"name\"></div>\n                  <div class=\"compact-field\"><label>Сторона</label><select data-unit-detail-field=\"side\"><option value=\"blue\" ${unit.side === 'blue' ? 'selected' : ''}>Синие</option><option value=\"red\" ${unit.side === 'red' ? 'selected' : ''}>Красные</option><option value=\"neutral\" ${unit.side === 'neutral' ? 'selected' : ''}>Нейтральные</option></select></div>\n                  <div class=\"compact-field\"><label>Архетип</label><select data-unit-detail-field=\"archetype\">${optionList(Object.keys(archetypeProfileSets), unit.archetype)}</select></div>\n                  <div class=\"compact-field\"><label>Положение тела</label><div class=\"pose-tools\">\n                    <button class=\"icon-tool ${unit.pose === 'stand' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"stand\" title=\"Стоит\">${iconSvg('stand')}</button>\n                    <button class=\"icon-tool ${unit.pose === 'crouch' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"crouch\" title=\"Сидит\">${iconSvg('crouch')}</button>\n                    <button class=\"icon-tool ${unit.pose === 'prone' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"prone\" title=\"Лежит\">${iconSvg('prone')}</button>\n                  </div></div>\n                </div>\n              </div>\n            </section>\n            <section class=\"compact-section\">\n              <div class=\"compact-section__head\"><span class=\"compact-section__title\">Положение на карте</span><div class=\"unit-quick-actions\"><button class=\"icon-tool\" type=\"button\" data-unit-action=\"move\" title=\"Переместить\">${iconSvg('move')}</button><button class=\"icon-tool\" type=\"button\" data-unit-action=\"rotate\" title=\"Повернуть\">${iconSvg('rotate')}</button></div></div>\n              <div class=\"compact-section__body\"><div class=\"unit-coordinate-row\"><div class=\"compact-field\"><label>X, % поля</label><input type=\"number\" step=\"0.1\" value=\"${unit.x.toFixed(1)}\" data-unit-detail-field=\"x\"></div><div class=\"compact-field\"><label>Y, % поля</label><input type=\"number\" step=\"0.1\" value=\"${unit.y.toFixed(1)}\" data-unit-detail-field=\"y\"></div><div class=\"compact-field\"><label>Поворот, °</label><input type=\"number\" value=\"${unit.heading}\" data-unit-detail-field=\"heading\"></div></div></div>\n            </section>`;\n        }\n        if (state.unitDetailsTab === 'profiles') {\n          return `\n            <section class=\"compact-section\"><div class=\"compact-section__head\"><span class=\"compact-section__title\">Набор профилей</span></div><div class=\"compact-section__body\"><div class=\"unit-detail-grid\">\n              <div class=\"compact-field\"><label>Профиль поведения</label><select data-unit-detail-field=\"behaviorProfile\">${optionList(profileOptions.behaviorProfile, unit.behaviorProfile)}</select></div>\n              <div class=\"compact-field\"><label>Профиль внимания</label><select data-unit-detail-field=\"attentionProfile\">${optionList(profileOptions.attentionProfile, unit.attentionProfile)}</select></div>\n              <div class=\"compact-field\"><label>Профиль движения</label><select data-unit-detail-field=\"movementProfile\">${optionList(profileOptions.movementProfile, unit.movementProfile)}</select></div>\n            </div><div class=\"profile-set-note\">Показатели профилей доступны только для просмотра. Редактирование выполняется через верхний раздел «Редакторы».</div>\n            ${profileReadOnlyBlock('Поведение', unit.behaviorProfile, [['Осторожность','Высокая'],['Склонность искать укрытие','Высокая'],['Реакция на подавление','Осторожная'],['Навыки','Определяются профилем']])}\n            ${profileReadOnlyBlock('Внимание', unit.attentionProfile, [['Ширина сектора','Средняя'],['Частота проверки тыла','Обычная'],['Приоритет угроз','Ближайшие']])}\n            ${profileReadOnlyBlock('Движение', unit.movementProfile, [['Предпочтительная скорость','Средняя'],['Использование укрытий','Включено'],['Допустимый риск маршрута','Низкий']])}\n            </div></section>`;\n        }\n        if (state.unitDetailsTab === 'weapon') {\n          return `\n            <section class=\"compact-section\"><div class=\"compact-section__head\"><span class=\"compact-section__title\">Вооружение и боезапас</span></div><div class=\"compact-section__body\"><div class=\"unit-detail-grid\">\n              <div class=\"compact-field compact-field--wide\"><label>Основное оружие</label><select data-unit-detail-field=\"weapon\">${optionList(['Винтовка Мосина','ППШ-41','Пулемёт ДП-27','Пистолет ТТ','Карабин 98k','Не задано'], unit.weapon)}</select></div>\n              <div class=\"compact-field\"><label>Патронов в оружии</label><input type=\"number\" min=\"0\" value=\"${unit.loadedAmmo}\" data-unit-detail-field=\"loadedAmmo\"></div>\n");
